css:
@font-face { font-family: 'ShunxiJinghuaSong'; src: url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/font/%E4%BA%AC%E8%8F%AF%E8%80%81%E5%AE%8B%E4%BD%93v3.0.woff2') format('woff2'); font-weight: 400; font-style: normal; font-display: swap; }
.prose-chapter { position: relative; isolation: isolate; box-sizing: border-box; overflow: hidden; width: 100%; max-width: 720px; min-width: 0; margin: 0 auto; padding: 44px 44px 48px 108px; border: 0; border-radius: 0; background: #F8F4E9 url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/shunxi/gufengbackground.png') repeat; background-size: 543px 724px; font-family: var(--reader-font); font-size: var(--reader-size); line-height: var(--reader-leading); color: var(--reader-ink); font-weight: 400; font-style: normal; box-shadow: none; }
.prose-chapter::before { content: ''; position: absolute; top: 0; bottom: 0; left: 14px; width: 66px; background-image: url('https://pub-9cfdbb4d14064a6dbe0397ffdff85f4b.r2.dev/shunxi/gufengleft.png'); background-position: center top; background-size: 280px auto; background-repeat: repeat-y; filter: saturate(.8); pointer-events: none; z-index: -1; }
.prose-title { margin: 0 0 30px; padding: 0; font-family: inherit; font-size: 28px; line-height: 1.6; font-weight: 400; letter-spacing: .12em; text-indent: 0; text-align: center; color: #393D32; overflow-wrap: anywhere; text-shadow: none; }
.paragraph { margin: 0 0 1.3em; padding: 0; font-family: inherit; font-size: inherit; font-weight: 400; font-style: normal; line-height: inherit; letter-spacing: .035em; text-indent: 0; text-align: left; overflow-wrap: anywhere; background: transparent; text-shadow: none; }
.paragraph:last-of-type { margin-bottom: 0; }
.paragraph q, .paragraph .prose-quote { color: #AB3D32; background: transparent; padding: 0; quotes: none; font-weight: inherit; font-style: inherit; text-decoration: none; }
.paragraph strong { color: #30352D; font-weight: 700; background: transparent; }
.paragraph em { color: #666D58; font-style: italic; background: transparent; }
.paragraph del { color: #807C70; text-decoration: line-through; text-decoration-thickness: 1px; background: transparent; }
.paragraph code { font-family: inherit; font-size: .9em; color: #685B4A; background: transparent; padding: 0; }
@media (max-width: 500px) { .prose-chapter { padding: 30px 22px 34px 76px; } .prose-chapter::before { left: 8px; width: 48px; background-size: 204px auto; } .prose-title { font-size: 26px; margin-bottom: 26px; } }
@media (max-width: 350px) { .prose-chapter { padding-left: 62px; padding-right: 18px; } .prose-chapter::before { left: 6px; width: 40px; background-size: 170px auto; } }

/* 瞬息统一阅读字号 */
.prose-chapter,.prose-chapter .paragraph{font-size:14px!important}.prose-chapter .prose-title{font-size:26px!important}
